async function registrarTrilha(s) {
    if (trilhaNestaCarga) return trilha;
    if (!s || s.autorizada !== true) return trilha;
    const c = client();
    if (!c) { trilha.erro = 'sem cliente'; return trilha; }
    trilhaNestaCarga = true; trilha.tentada = true;
    try {
      const u = await c.auth.getUser();
      const ator = (u && u.data && u.data.user) ? u.data.user.id : null;
      if (!ator) { trilha.erro = 'sem utilizador na sessão'; trilhaNestaCarga = false; return trilha; }
      const { error } = await c.from('bfr_municipal_audit').insert({ actor: ator, action: 'painel_aberto', entity: SECT, detail: { tab: estado.tab } });
      trilha.escrita = !error; trilha.erro = error ? String(error.message || error.code) : '';
      if (!error) trilha.acoes.push('painel_aberto:' + SECT + ':' + estado.tab);
    } catch (e) { trilha.escrita = false; trilha.erro = String((e && e.message) || e); trilhaNestaCarga = false; }
    return trilha;
  }
